/bin/bash -lc "python3 - <<'PY'
import csv
with open('docs/source-registry.csv', newline='', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        try: i=int(row['id'])
        except: continue
        if 56 <= i <= 64:
            print('\\nID', i)
            for k in ('title','source_name','url','evidence_class','access_status','status','scope_notes','notes'):
                if k in row and row[k]: print(f'{k}: {row[k]}')
            print(row)
PY"

